CREATE TABLE IF NOT EXISTS blue_carbon_methodologies (methodology_id VARCHAR(120) NOT NULL, version VARCHAR(32) NOT NULL, name VARCHAR(255) NOT NULL, ecosystem_types VARCHAR(32)[] NOT NULL, status VARCHAR(32) NOT NULL CHECK (status IN ('draft','internal_review','approved','retired')), effective_from DATE, effective_to DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (methodology_id, version));
INSERT INTO blue_carbon_methodologies (methodology_id,version,name,ecosystem_types,status) VALUES ('blue-carbon-initial-v1','1.0.0','Blue Carbon Initial Methodology',ARRAY['mangrove']::VARCHAR[],'internal_review') ON CONFLICT DO NOTHING;
ALTER TABLE blue_carbon_projects ADD COLUMN IF NOT EXISTS methodology_version VARCHAR(32), ADD COLUMN IF NOT EXISTS area_hectares NUMERIC(14,6), ADD COLUMN IF NOT EXISTS submitted_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS submitted_by VARCHAR(255);
UPDATE blue_carbon_projects SET methodology_version='1.0.0' WHERE methodology_id='blue-carbon-initial-v1' AND methodology_version IS NULL;
CREATE TABLE IF NOT EXISTS blue_carbon_baselines (baseline_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL, org_id VARCHAR(255) NOT NULL, baseline_date DATE NOT NULL, source_label VARCHAR(255) NOT NULL, summary TEXT NOT NULL, source_uri TEXT, created_by VARCHAR(255), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT blue_carbon_baseline_project_org_fk FOREIGN KEY (project_id,org_id) REFERENCES blue_carbon_projects(project_id,org_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS blue_carbon_baselines_project_idx ON blue_carbon_baselines(project_id,baseline_date DESC);
CREATE TABLE IF NOT EXISTS blue_carbon_project_status_history (history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL, org_id VARCHAR(255) NOT NULL, from_status VARCHAR(32), to_status VARCHAR(32) NOT NULL, reason TEXT, changed_by VARCHAR(255), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT blue_carbon_status_project_org_fk FOREIGN KEY (project_id,org_id) REFERENCES blue_carbon_projects(project_id,org_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS blue_carbon_status_history_project_idx ON blue_carbon_project_status_history(project_id,created_at DESC);
